        "completion_date": "2027-08-15",
        "conditions": [
          "Duchenne Muscular Dystrophy (DMD)",
          "Virtual Reality"
        ],
        "enrollment": 36,
        "interventions": [
          {
            "description": "This intervention involves the use of fully immersive virtual reality (VR) applications delivered through the Meta Quest 3 headset, integrated with hand-tracking technology. Participants engage in three custom-designed VR games aimed at improving shoulder, elbow, wrist, and hand functions. The games are tailored to individual functional levels and include progressive difficulty. Sessions are conducted twice per week for 8 weeks, each lasting approximately 40 minutes, under the supervision of a physiotherapist. This intervention is combined with conventional physiotherapy (excluding functional upper extremity exercises).",
            "id": 1,
            "name": "Virtual Reality + Conventional Physiotherapy",
            "other_names": [],
            "type": {
              "authority": "clinicaltrials.gov",
              "code": "BEHAVIORAL",
              "display": null,
              "recognized_meaning": null,
              "vocabulary_version": null
            }
          },
          {
            "description": "This intervention consists of a standard physiotherapy program for individuals with Duchenne Muscular Dystrophy. It includes aerobic exercises, strengthening exercises, stretching routines, postural training, respiratory exercises, and functional upper extremity exercises. The sessions are delivered by a physiotherapist twice weekly for 8 weeks, with each session lasting approximately 40 minutes.",
            "id": 2,
            "name": "Conventional Physiotherapy",
            "other_names": [],
            "type": {
              "authority": "clinicaltrials.gov",
              "code": "BEHAVIORAL",
              "display": null,
              "recognized_meaning": null,
              "vocabulary_version": null
            }
          },
          {
            "description": "Before initiation of the randomized controlled trial, the VR rehabilitation platform underwent a preliminary formative usability evaluation involving five individuals with Duchenne muscular dystrophy (DMD). During this pre-evaluation phase, perceived usability, enjoyment, ease of use, and potential VR-related discomfort associated with the VR games were assessed using standardized outcome measures, including the System Usability Scale (SUS), the enjoyment subscale of the Game User Experience Satisfaction Scale (GUESS), and the Virtual Reality Sickness Questionnaire (VRSQ). In addition, qualitative user feedback was collected through open-ended questions regarding gameplay experience, perceived difficulties, and suggestions for improvement. Findings from this formative evaluation were used to optimize gameplay mechanics, interaction design, and overall system usability prior to implementation of the randomized controlled trial.",
            "id": 3,
            "name": "Formative Usability Evaluation of the VR Rehabilitation Platform",
            "other_names": [],
            "type": {
              "authority": "clinicaltrials.gov",
              "code": "OTHER",
              "display": null,
              "recognized_meaning": null,
              "vocabulary_version": null
            }
          }
